class Client:
    def __init__(self) -> None:
        self._pending: dict[str, asyncio.Future[Reply]] = {}

    async def call(self, body: str) -> Reply:
        loop = asyncio.get_running_loop()
        cid, fut = uuid.uuid4().hex, loop.create_future()
        self._pending[cid] = fut                       # register BEFORE send
        try:
            await self._transport.publish(Request(cid, body))
            return await asyncio.wait_for(fut, timeout=5.0)   # cancels fut on timeout
        finally:
            self._pending.pop(cid, None)

    def _on_reply(self, msg) -> None:
        fut = self._pending.get(msg.correlation_id)
        if fut is not None and not fut.done():
            fut.set_result(msg.payload)                # unknown id: ignore

