class BlockingClient:
    def __init__(self) -> None:
        self._pending: dict[str, Future] = {}
        self._lock = threading.Lock()
        threading.Thread(target=self._reader, daemon=True).start()

    def call(self, body: str) -> Reply:
        cid, fut = uuid.uuid4().hex, Future()
        with self._lock:
            self._pending[cid] = fut               # register BEFORE send
        self._send(Request(cid, body))
        try:
            return fut.result(timeout=5)           # raises TimeoutError on expiry
        finally:
            with self._lock:
                self._pending.pop(cid, None)

    def _reader(self) -> None:                     # the transport's blocking loop
        for msg in self._transport:
            with self._lock:
                fut = self._pending.get(msg.correlation_id)
            if fut is not None and not fut.done():
                fut.set_result(msg.payload)        # unknown id: drop
